mapper.sql:
SELECT record.*
FROM hr_attendance_record record
WHERE record.tenant_id = #{tenantId} AND record.deleted = 0
AND record.employee_id = #{query.employeeId}
AND record.shift_id = #{query.shiftId}
AND record.status = #{query.status}
AND record.attendance_date >= #{query.startDate}
AND record.attendance_date <= #{query.endDate}

    AND EXISTS (
        SELECT 1 FROM hr_employee employee
        WHERE employee.id = record.employee_id AND employee.tenant_id = #{tenantId} AND employee.deleted = 0
        AND employee.dept_id = #{query.deptId}


                AND employee.user_id = #{scope.userId}

                    AND employee.dept_id IN
                    #{departmentId}

                AND 1 = 0


    )

ORDER BY record.update_time DESC, record.id DESC

mapper.select:
SELECT * FROM hr_attendance_record
WHERE tenant_id = #{tenantId} AND employee_id = #{employeeId} AND deleted = 0
  AND attendance_date BETWEEN #{from} AND #{to}

mapper.update:
UPDATE hr_attendance_record original JOIN ( VALUES
ROW(#{record.id}, #{record.version}, #{record.shiftId}, #{record.workMinutes}, #{record.expectedMinutes}, #{record.lateMinutes}, #{record.earlyExitMinutes}, #{record.overtimeMinutes}, #{record.firstCheckinTime}, #{record.lastCheckoutTime}, #{record.checkinCount}, #{record.halfDayFlag}, #{record.absentFlag}, #{record.dateType}, #{record.status}, #{record.recalcTime}, #{record.remark}, #{record.updateBy}, #{record.updateTime})
) fresh(id, expected_version, shift_id, work_minutes, expected_minutes, late_minutes, early_exit_minutes, overtime_minutes, first_checkin_time, last_checkout_time, checkin_count, half_day_flag, absent_flag, date_type, status, recalc_time, remark, update_by, update_time) ON fresh.id = original.id AND fresh.expected_version = original.version SET original.shift_id = fresh.shift_id, original.work_minutes = fresh.work_minutes, original.expected_minutes = fresh.expected_minutes, original.late_minutes = fresh.late_minutes, original.early_exit_minutes = fresh.early_exit_minutes, original.overtime_minutes = fresh.overtime_minutes, original.first_checkin_time = fresh.first_checkin_time, original.last_checkout_time = fresh.last_checkout_time, original.checkin_count = fresh.checkin_count, original.half_day_flag = fresh.half_day_flag, original.absent_flag = fresh.absent_flag, original.date_type = fresh.date_type, original.status = fresh.status, original.recalc_time = fresh.recalc_time, original.remark = fresh.remark, original.manual_adjusted_flag = 0, original.version = original.version + 1, original.update_by = fresh.update_by, original.update_time = fresh.update_time WHERE original.tenant_id = #{tenantId} AND original.employee_id = #{employeeId} AND original.deleted = 0

UPDATE hr_attendance_checkin checkin
JOIN hr_attendance_record record ON record.tenant_id = checkin.tenant_id
    AND record.employee_id = checkin.employee_id AND record.attendance_date = checkin.attendance_date
    AND record.deleted = 0
SET checkin.attendance_record_id = record.id
WHERE checkin.tenant_id = #{tenantId} AND record.tenant_id = #{tenantId}
    AND checkin.employee_id = #{employeeId}
    AND checkin.attendance_date IN
    #{date}
    AND (checkin.attendance_record_id IS NULL OR checkin.attendance_record_id != record.id)

